//! Cross-checks the DocLang export against Docling's PDF groundtruth.
//!
//! Docling ships serialized `DoclingDocument`s (`tests/data/pdf/groundtruth/
//! *.json`) plus their PDF sources (`tests/data/pdf/sources/`). The exports
//! under `tests/fixtures/doclang/` — regenerated by
//! `scripts/export_docling_doclang.py` from those JSONs — are the source of
//! truth here: every character the reference extraction reports must survive
//! anydoc's export, on the same codepoints, ignoring markup and ordering.
//!
//! The harness locates the checkout via `DOCLING_PDF_TESTDATA` (default:
//! `../docling/tests/data/pdf` relative to this crate) and skips when absent.
//!
//! Known divergences, documented rather than asserted away:
//! - `newspaper-00`: pdf-inspector rejects the content stream; the Markdown
//!   path fails identically.
//! - `right_to_left_*`: characters match but anydoc keeps PDF visual order
//!   where Docling emits bidi-reordered logical text.
//! - Structure: Docling's layout model detects borderless tables, headings,
//!   captions, and page furniture beyond anydoc's tagged/ruled-table and
//!   font heuristics; counts therefore differ by design.

mod common;

use common::fixture_root;
use std::collections::HashMap;
use std::io::{Cursor, Read};
use std::path::{Path, PathBuf};

/// Root of Docling's `tests/data/pdf` directory, when a checkout is present.
fn docling_testdata() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("DOCLING_PDF_TESTDATA") {
        let dir = PathBuf::from(dir);
        return dir.join("sources").is_dir().then_some(dir);
    }
    let sibling = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()?
        .join("docling")
        .join("tests")
        .join("data")
        .join("pdf");
    sibling.join("sources").is_dir().then_some(sibling)
}

/// Unzip `document.xml` out of a `.dclx` archive.
fn document_xml(dclx: &[u8]) -> String {
    let mut zip = zip::ZipArchive::new(Cursor::new(dclx)).unwrap();
    let mut f = zip.by_name("document.xml").unwrap();
    let mut buf = String::new();
    f.read_to_string(&mut buf).unwrap();
    buf
}

/// Well-formed XML (quick-xml parses a full event stream without error).
fn assert_well_formed(xml: &str) {
    let mut reader = quick_xml::Reader::from_str(xml);
    loop {
        match reader.read_event() {
            Ok(quick_xml::events::Event::Eof) => return,
            Ok(_) => {}
            Err(e) => panic!("malformed XML: {e}"),
        }
    }
}

/// Character multiset of the document's text content: markup and CDATA
/// wrappers dropped, entities decoded, whitespace ignored.
fn text_chars(xml: &str) -> HashMap<char, usize> {
    let mut out = HashMap::new();
    let mut reader = quick_xml::Reader::from_str(xml);
    loop {
        match reader.read_event() {
            Ok(quick_xml::events::Event::Eof) => break,
            Ok(quick_xml::events::Event::Text(e)) => {
                let decoded = e.decode().unwrap();
                let text = match quick_xml::escape::unescape(&decoded) {
                    Ok(text) => text,
                    Err(_) => decoded,
                };
                for c in text.chars() {
                    if !c.is_whitespace() {
                        *out.entry(c).or_default() += 1;
                    }
                }
            }
            Ok(quick_xml::events::Event::CData(e)) => {
                for c in e.decode().unwrap().chars() {
                    if !c.is_whitespace() {
                        *out.entry(c).or_default() += 1;
                    }
                }
            }
            Ok(_) => {}
            Err(e) => panic!("malformed XML: {e}"),
        }
    }
    out
}

/// Share of the reference's characters (multiset) present in ours.
fn coverage(reference: &HashMap<char, usize>, ours: &HashMap<char, usize>) -> f64 {
    let total: usize = reference.values().sum();
    if total == 0 {
        return 1.0;
    }
    let covered: usize =
        reference.iter().map(|(c, n)| (*n).min(ours.get(c).copied().unwrap_or(0))).sum();
    covered as f64 / total as f64
}

/// Every paired PDF converts to a well-formed `.dclx` whose text covers the
/// Docling reference's characters. `newspaper-00` is a known pdf-inspector
/// failure and asserted to error instead.
#[test]
fn docling_groundtruth_text_coverage() {
    let Some(root) = docling_testdata() else {
        eprintln!("docling testdata not found; set DOCLING_PDF_TESTDATA — skipping");
        return;
    };
    let sources = root.join("sources");
    let groundtruth = fixture_root().join("doclang");

    let mut checked = 0;
    for entry in std::fs::read_dir(&sources).unwrap() {
        let path = entry.unwrap().path();
        if path.extension().is_none_or(|e| e != "pdf") {
            continue;
        }
        let name = path.file_stem().unwrap().to_string_lossy().to_string();
        let reference_path = groundtruth.join(format!("{name}.doclang"));
        if !reference_path.exists() {
            continue; // e.g. skipped_*.pdf have no serialized document
        }

        let bytes = std::fs::read(&path).unwrap();
        let result = anydoc::to_doclang_bytes(&bytes, anydoc::Format::Pdf, None);
        if name == "newspaper-00" {
            // Known gap: pdf-inspector rejects the page content stream
            // (the Markdown path errors identically).
            assert!(result.is_err(), "newspaper-00 unexpectedly converts");
            continue;
        }
        let dclx = result.unwrap_or_else(|e| panic!("{name}: export failed: {e}"));
        let xml = document_xml(&dclx);
        assert_well_formed(&xml);

        let reference = text_chars(&std::fs::read_to_string(&reference_path).unwrap());
        let cov = coverage(&reference, &text_chars(&xml));
        assert!(
            cov >= 0.95,
            "{name}: text coverage {:.1}% below 95% of the Docling reference",
            cov * 100.0
        );
        checked += 1;
    }
    assert!(checked > 0, "no docling groundtruth pairs were exercised");
    eprintln!("checked {checked} docling groundtruth documents");
}
